        let m3 = v[0] * v[1];
        let m4 = v[0] * v[2];
        let m5 = v[1] * v[2];
        let m6 = m0 - m1;
        let m7 = m0 + m1;
        let m8 = m2 - m6;
        let m9 = m2 + m6;
        let m10 = m2 - m7;
        let m11 = -m8;
        let m12 = m3 * T::from_i64(2);
        let m13 = m4 * T::from_i64(2);
        let m14 = -m9;
        let m15 = m5 * T::from_i64(2);
        let m16 = m2 + m7;
        let x = x.c.map(gx::SlotArr::<S, T>);
